sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    try {

        var prompts = ["Business Rule", "Script Include function"];
        var setFields = ["script", "script_includes"];

        for (var j = 0; j < prompts.length; j++) {
            g_form.addErrorMessage(j);
			g_form.addInfoMessage('field ' + setFields[j]);
			g_form.addInfoMessage('prompts ' + prompts[j]);
        }

        for (var i = 0; i < prompts.length; i++) {
            g_form.addErrorMessage(i);

            var prompt = 'For servicenow write a script ' + prompts[i] + ' to ' + g_form.getValue('script_name').toString() + ". " + 'Please reply back only the script removing all explanations,comments, new line tags  or anything which is not supported in servicenow syntax.';

            var getServerResponse = new GlideAjax('x_938076_now_utils.getGeminiResponse');
            getServerResponse.addParam('sysparm_name', 'geminiAutoGenerateScript');
            getServerResponse.addParam('sysparm_prompt', prompt);
            getServerResponse.getXMLAnswer(handleResp);

            function handleResp(responseAnswer) {
                g_form.addInfoMessage('Promots ' + prompt);
               // g_form.addInfoMessage('field ' + setFields[i]);

                var geminiAnswer = JSON.parse(responseAnswer)
                g_form.setValue(setFields[i].toString(), geminiAnswer.answer);
            }

        }

    } catch (ex) {
        g_form.addInfoMessage('Error ' + ex);
    }




}
